        String input = "<script>alert('aaa');</script>";
        String expected = "<script>alert('aaa');<https://script>";
        String actual = StringEscapeUtils.escapeJavaScript(input);
        assertEquals("StringEscapeUtils.escapeJavaScript() should escape '/' to '<redacted URL>'", expected, actual);
    }
}

package org.apache.commons.lang3.time;

import junit.framework.TestCase;

public class StopWatchBugOriginTest extends TestCase {

    public void testSuspendStopRelationship() throws Exception {
        StopWatch sw = new StopWatch();

        sw.start();
        Thread.sleep(100);
        sw.suspend();
        long suspendTime = sw.getTime();

        Thread.sleep(200);

        // According to the report, if we call stop() while suspended, 
        // the time should not increase.
        sw.stop();
        long stopTime = sw.getTime();

        assertEquals("The time after stop() should be the same as the time at suspend()", suspendTime, stopTime);
    }
}

package org.apache.commons.lang3;

import java.util.Locale;
import junit.framework.TestCase;

public class LocaleUtilsBugOriginTest extends TestCase {

    public void testIsAvailableLocaleNPE() {
        // According to the report, cAvailableLocaleSet might not be initialized
        // if availableLocaleSet() hasn't been called yet.
        // isAvailableLocale(Locale) uses it directly.

        // We use a common locale to check if it's available.
        // The bug report suggests that calling this method first (or without 
        // prior initialization of the set) triggers a NullPointerException.
        try {
            LocaleUtils.isAvailableLocale(Locale.US);
        } catch (NullPointerException e) {
            fail("isAvailableLocale(Locale) threw NullPointerException: " + e.getMessage());
        }
    }
}

