package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {
    public void testEscapeXmlWithSupplementaryCharacters() {
        // A supplementary character (U+1D306, TETRAGRAM FOR CENTRE)
        // In UTF-16, it is represented as \uD834\uDF06
        String input = "\uD834\uDF06";
        String escaped = StringEscapeUtils.escapeXml(input);

        // The reporter expects the code point to be treated as a single character.
        // For XML, characters above 0x7F are often escaped as numeric entities.
        // U+1D306 is 119558 in decimal.
        // If the bug is present, it might escape the surrogates individually or fail.
        // Expected: "&#119558;"
        assertEquals("&#119558;", escaped);
    }
}
